'use strict';
const root=document.getElementById('game'),escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readGame=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},saveGame=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let selected=[0,1,5],state=null,soft=readGame('tw-game-soft',false)===true,collection=readGame('tw-game-endings',[]);if(!Array.isArray(collection))collection=[];
let resumable=SurvivalEngine.restore(readGame('tw-game-save',null));document.getElementById('soft').checked=soft;
const money=n=>n.toLocaleString('ko-KR')+'원';
const speak=s=>escapeHTML(soft?s.replace(/ㅋㅋ시발/g,'ㅋㅋ아이고').replace(/씨바|시발|스바|ㅅㅂ|존나/g,'아이고'):s);
const face=p=>`<span class="avatar" style="background-position:${p.id%4*100/3}% ${Math.floor(p.id/4)*50}%" aria-hidden="true"></span>`;
function bubbles(p,lines){return `<div class="speaker">${face(p)}<div><strong>${p.name}</strong><div class="burst">${lines.map(l=>`<span>${speak(l)}</span>`).join('')}</div></div></div>`;}
function persist(){saveGame('tw-game-save',state);}
function lobby(){resumable=SurvivalEngine.restore(readGame('tw-game-save',null));state=null;root.innerHTML=`<section class="intro"><p class="eyebrow">친구 셋 + 총무 하나 · 선택형 생존게임</p><h1>개테천<br><em>모임 대작전</em><span>오늘도 무사히 집에 갈 수 있을까?</span></h1><p>예산은 12만 원. 갈 곳은 많은데 의견은 더 많다.<br>밥, 웨이팅, 한 판만 더 사이에서 모임을 지켜라.</p><div class="rules"><span>₩ 공동 예산</span><span>♥ 체력</span><span>🍚 배부름</span><span>✦ 분위기</span></div></section><section class="party"><div class="section-head"><h2>오늘 같이 나갈 친구</h2><span id="count">${selected.length} / 3</span></div><p class="muted">친구를 바꾸면 반응과 선호도도 달라집니다. 아래는 창작 대사 샘플.</p><div class="cast">${survivalCast.map(p=>`<button class="cast-card ${selected.includes(p.id)?'selected':''}" data-person="${p.id}" aria-pressed="${selected.includes(p.id)}">${face(p)}<strong>${p.name}</strong><small>${p.tag}</small><span class="sample">${p.sample.map(speak).join('<br>')}</span></button>`).join('')}</div><div class="launch"><button class="primary" id="start" ${selected.length!==3?'disabled':''}>이 멤버로 출발 →</button>${resumable?'<button id="resume">지난 모임 이어하기</button>':''}</div><p class="muted">수집한 엔딩 ${new Set(collection).size} / 6 · 한 판 약 3분</p></section>`;root.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{let id=Number(b.dataset.person);if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<3)selected.push(id);else{document.getElementById('count').textContent='3명까지 선택 · 한 명을 먼저 해제';return;}lobby();});document.getElementById('start').onclick=()=>{state=SurvivalEngine.create(selected);persist();render();window.scrollTo(0,0)};const resume=document.getElementById('resume');if(resume)resume.onclick=()=>{state=resumable;selected=[...state.party];render();window.scrollTo(0,0)};}
function stats(){return `<div class="stats"><div class="cash"><span>네 사람의 공동 예산</span><strong>${money(state.budget)}</strong></div>${[['energy','체력','♥'],['fullness','배부름','🍚'],['mood','분위기','✦']].map(([k,n,i])=>`<div class="meter ${state[k]<25?'danger':''}"><span>${i} ${n}<b>${state[k]}</b></span><progress max="100" value="${state[k]}" aria-label="${n}"></progress></div>`).join('')}</div>`;}
function recap(){return `<details><summary>오늘의 선택 기록 (${state.history.length})</summary><ol>${state.history.map(h=>{const sc=survivalScenes.find(x=>x.id===h.scene),c=sc.choices.find(x=>x.id===h.choice);return `<li><small>${sc.time} · ${sc.location}</small><br>${c.label}${h.event?`<br><small>돌발 상황: ${survivalEvents.find(e=>e.id===h.event).title}</small>`:''}</li>`}).join('')}</ol></details>`;}
function render(){if(!state)return lobby();const ended=SurvivalEngine.ending(state);if(state.phase==='end'){if(!collection.includes(ended[0])){collection.push(ended[0]);saveGame('tw-game-endings',collection);}root.innerHTML=`<section class="ending"><p class="eyebrow">모임 종료 · ENDING ${collection.length} / 6</p><div class="end-icon">${ended[0]==='perfect'?'🏆':ended[0]==='taxi'?'🚕':'🏁'}</div><h1>${ended[1]}</h1><p>${ended[2]}</p><div class="friends">${state.party.map(id=>face(survivalCast[id])).join('')}</div>${stats()}${recap()}<div class="launch"><button class="primary" id="again">같은 멤버로 다시 도전</button><button id="party">멤버 바꾸기</button><button id="share">결과 복사</button></div><p id="copy-status" role="status"></p></section>`;document.getElementById('again').onclick=()=>{state=SurvivalEngine.create(state.party);persist();render()};document.getElementById('party').onclick=lobby;document.getElementById('share').onclick=async()=>{const text=`개테천 모임 대작전: ${ended[1]}\n${state.party.map(id=>survivalCast[id].name).join(' · ')}\n남은 예산 ${money(state.budget)} / 분위기 ${state.mood}\nhttps://inzae1.github.io/theme-wiki/game.html`;try{await navigator.clipboard.writeText(text);document.getElementById('copy-status').textContent='결과를 복사했습니다.'}catch{document.getElementById('copy-status').textContent=text}};return;}
const reaction=state.phase==='reaction',scene=survivalScenes[reaction?state.step-1:state.step],h=reaction?state.history.at(-1):null,c=reaction?scene.choices.find(c=>c.id===h.choice):null,event=h?.event?survivalEvents.find(e=>e.id===h.event):null;root.innerHTML=`<div class="play-top"><span>ROUND ${reaction?state.step:state.step+1} / 7</span><button id="back">멤버 선택</button></div><div class="steps" aria-hidden="true">${survivalScenes.map((s,i)=>`<span class="${i<state.step?'done':i===state.step?'current':''}"></span>`).join('')}</div>${stats()}<div class="play-grid"><section class="scene"><p class="eyebrow">${scene.time} · ${scene.location}</p><h1>${scene.title}</h1><p>${scene.intro}</p><div class="scene-art" aria-hidden="true">${{arrive:'🚉',food:'🍚',wait:'☕',move:'🚶',activity:'🎮',dinner:'🍜',home:'🌙'}[scene.id]}<span>개테천의 하루</span></div>${reaction?`<div class="chosen"><small>총무의 선택</small><strong>${c.label}</strong><p>지출 ${money(c.cost)} · 멤버 취향 반영 분위기 ${h.affinity>=0?'+':''}${h.affinity}</p></div>${event?`<aside class="event"><b>⚡ ${event.title}</b><p>${event.text}</p><small>${['budget','energy','fullness','mood'].filter(k=>event[k]).map(k=>`${{budget:'예산',energy:'체력',fullness:'배부름',mood:'분위기'}[k]} ${event[k]>0?'+':''}${k==='budget'?money(event[k]):event[k]}`).join(' · ')}</small></aside>`:''}<button class="primary next" id="next">${ended?'모임 결과 보기':'다음 장소로 →'}</button>`:`<div class="choices">${scene.choices.map(ch=>`<button data-choice="${ch.id}" ${ch.cost>state.budget?'disabled':''}><strong>${ch.label}</strong><small>${ch.note}${ch.cost>state.budget?' · 예산 부족':''}</small><span>체력 ${signed(ch.energy)} · 배부름 ${signed(ch.fullness)} · 분위기 ${signed(ch.mood)}</span></button>`).join('')}</div>`}</section><section class="chat"><div class="chat-head"><b>개테천 · 오늘 모임</b><span>4명</span></div><p class="chat-date">${reaction?'선택에 대한 친구들의 반응':'친구들이 각자 의견을 내는 중'}</p>${state.party.map(id=>{const p=survivalCast[id];return bubbles(p,reaction?p.react[ended&&state.step<7?'fail':c.reply]:p.voices[scene.id==='dinner'&&state.fullness<30?'food':scene.id])}).join('')}<div class="chat-note">말투를 참고한 창작 대화</div></section></div>${recap()}`;document.getElementById('back').onclick=lobby;if(reaction)document.getElementById('next').onclick=()=>{state=SurvivalEngine.next(state);persist();render();window.scrollTo(0,0)};else root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state=SurvivalEngine.choose(state,b.dataset.choice);persist();render();document.querySelector('.chat').scrollIntoView({block:'nearest',behavior:'smooth'})});}
function signed(n){return (n>0?'+':'')+n;}
document.getElementById('soft').onchange=e=>{soft=e.target.checked;saveGame('tw-game-soft',soft);render()};lobby();
